"""중2 영어 진단 세트."""
from question_bank.elementary._common import make_question,validate_elementary_questions
L,S="중2","영어";K=[3,3,3,4,2,3,2,1,2,2,5,1,2,2,2];T=[40,40,35,35,40,40,40,40,40,50,55,55,45,50,50]
def q(n,a,s,t,o,c,ad=False):return make_question(f"M2ENG-{n:02d}",L,S,a,s,t,o,c,T[n-1],f"{o[c-1]}가 문법과 문맥에 맞습니다.",f"{s}를 다시 확인할 필요가 있음.",ad)
D=[("시제·표현","현재완료","I ___ my homework already.",["finish","finished","have finished","am finishing","will finish"],3),("문장 구조","수동태","The bridge ___ in 2010.",["builds","built","was built","is building","has build"],3),("동명사·부정사","동명사","She enjoys ___ books.",["read","to read","reading","reads","readed"],3),("동명사·부정사","to부정사","I want ___ abroad someday.",["travel","traveled","travels","to travel","traveling"],4),("관계사","주격 관계대명사","The boy ___ is singing is my brother.",["which","who","where","when","what"],2),("관계사","목적격 관계대명사","This is the book ___ I bought yesterday.",["who","where","which","when","whose"],3),("비교 표현","비교급","This book is ___ than that one.",["interesting","more interesting","most interesting","interest","the most interesting"],2),("구문","too ... to","He was too tired to walk. 알맞은 뜻은?",["그는 너무 피곤해서 걸을 수 없었다.","그는 피곤했지만 계속 걸었다.","그는 걷기 위해 피곤했다.","그는 전혀 피곤하지 않았다.","그는 걷는 것을 좋아했다."],1),("접속사","although","Although it was raining, we went hiking. 알맞은 뜻은?",["비가 와서 등산을 취소했다.","비가 왔지만 우리는 등산을 갔다.","비가 오기 전에 등산을 갔다.","등산 중에만 비가 멈췄다.","비가 오지 않아 등산을 갔다."],2),("간접의문문","어순","Do you know ___?",["where does he live","where he lives","where lives he","he lives where","where did he lives"],2),("읽기 이해","세부 정보","The recycling club meets every Friday after school. 언제 모이나요?",["Monday morning","Wednesday lunch","Thursday evening","Saturday","Friday after school"],5),("읽기 이해","행동의 이유 추론","Joon checked the bus schedule twice and left home early. 가장 자연스러운 이유는?",["버스를 놓치지 않으려고","학교에 가지 않으려고","버스표를 잃어버려서","집에서 더 자려고","날씨를 확인하려고"],1),("어휘","문맥 어휘","reduce의 뜻으로 가장 알맞은 것은?",["늘리다","줄이다","반복하다","발견하다","교환하다"],2),("다음 단계 진입 탐색","가정법 과거 진입","If I were you, I ___ apologize.",["will","would","am","have","did"],2,True),("다음 단계 진입 탐색","분사 후치수식 진입","The boy standing by the door is my cousin. 내 사촌은 누구인가요?",["문을 닫는 소년","문 옆에 서 있는 소년","달리고 있는 소년","책을 읽는 소년","의자에 앉은 소년"],2,True)]
Q=[q(i+1,*x)for i,x in enumerate(D)];validate_elementary_questions(Q,K,555,100)
QUESTION_SET={"level":L,"subject":S,"curriculum":"2022 개정 교육과정 중학교 영어 참고","curriculum_year":2026,"test_version":"M2_ENG_2022R_2026_v1.0","core_count":13,"advance_count":2,"display_name":"중2 영어 진단","questions":Q}
